1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.Regions;
10	import org.springframework.samples.petclinic.model.OwnerTelephone;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
13	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
14	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
15	import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateFutureException;
16	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
17	import org.springframework.web.bind.annotation.RequestBody;
18	
19	/**
20	 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
21	 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
22	 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
23	 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
24	 * validation, is the authoritative implementation of the required-field rule.
25	 *
26	 * <p>The address is normalized (see {@link OwnerAddress}) before the required-field check, so an
27	 * address that is blank once whitespace is collapsed is rejected as missing. The normalized value is
28	 * written back onto the body so the normalized, abbreviation-expanded address is what gets stored,
29	 * returned and compared for household matching.
30	 *
31	 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
32	 * value that cannot form a valid E.164 number is rejected with a 400 via
33	 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
34	 * gets stored and returned.
35	 *
36	 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
37	 * syntactically valid address; otherwise the create is rejected with a 400 via
38	 * {@link OwnerEmailInvalidException}. A valid email is lower-cased and written back onto the body so
39	 * the lower-cased value is what gets stored and returned. The validated body is republished for
40	 * {@link BuildOwner}.
41	 */
42	public class ValidateOwner {
43	
44	    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
45	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
46	
47	    /** A postcode is a string of exactly four digits. */
48	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
49	
50	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
51	            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
52	            OwnerEmailInvalidException, OwnerPostcodeInvalidException,
53	            OwnerRegistrationDateFutureException {
54	        List<String> missing = new ArrayList<>();
55	        if (isBlank(request.getFirstName())) {
56	            missing.add("firstName");
57	        }
58	        if (isBlank(request.getLastName())) {
59	            missing.add("lastName");
60	        }
61	        String address = OwnerAddress.normalize(request.getAddress());
62	        if (address.isEmpty()) {
63	            missing.add("address");
64	        }
65	        if (isBlank(request.getCity())) {
66	            missing.add("city");
67	        }
68	        if (isBlank(request.getTelephone())) {
69	            missing.add("telephone");
70	        }
71	        if (!missing.isEmpty()) {
72	            throw new OwnerFieldsMissingException(missing);
73	        }
74	        request.setAddress(address);
75	        String e164 = OwnerTelephone.toE164(request.getTelephone());
76	        if (e164 == null) {
77	            throw new OwnerTelephoneInvalidException(request.getTelephone());
78	        }
79	        request.setTelephone(e164);
80	
81	        String email = request.getEmail();
82	        if (email != null) {
83	            if (!EMAIL.matcher(email).matches()) {
84	                throw new OwnerEmailInvalidException(email);
85	            }
86	            request.setEmail(email.toLowerCase());
87	        }
88	
89	        // Postcode is optional. When present it must be a 4-digit value that is valid for the
90	        // owner's city region; a city with no known region accepts any 4-digit value.
91	        String postcode = request.getPostcode();
92	        if (postcode != null) {
93	            if (!POSTCODE.matcher(postcode).matches()
94	                    || !Regions.postcodeMatchesCity(request.getCity(), postcode)) {
95	                throw new OwnerPostcodeInvalidException(postcode);
96	            }
97	        }
98	
99	        // Registration may be supplied but never dated in the future: a value later than the
100	        // server's current date is rejected with a 400.
101	        LocalDate registrationDate = request.getRegistrationDate();
102	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
103	            throw new OwnerRegistrationDateFutureException(registrationDate);
104	        }
105	
106	        validated.set(request);
107	    }
108	
109	    private static boolean isBlank(String value) {
110	        return value == null || value.isBlank();
111	    }
112	}
