1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerDailyLimitException;
9	
10	/**
11	 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 429 via
12	 * {@link OwnerDailyLimitException} when the maximum number of owners ({@value #MAX_OWNERS_PER_DAY})
13	 * already share the new owner's effective registration date, as determined by their
14	 * {@code registrationDate}. That effective date is the request's supplied date, or the server's
15	 * current date when omitted, rolled forward off any weekend to a business day (see {@link BusinessDay}),
16	 * so the limit counts owners per adjusted business day. The new owner is still unsaved — and is itself
17	 * dated that same business day (see {@link BuildOwner}) — so it is not counted against the limit.
18	 */
19	public class CheckOwnerDailyLimit {
20	
21	    /** At most this many owners may be created in a single day; the create of one more is rejected. */
22	    static final int MAX_OWNERS_PER_DAY = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws OwnerDailyLimitException {
26	        LocalDate businessDay = BusinessDay.effective(request.getRegistrationDate());
27	        // The new owner is still unsaved, so there is nothing to exclude from the count.
28	        int count = DailyRegistrations.countOn(ownerRepository, businessDay, null);
29	        if (count >= MAX_OWNERS_PER_DAY) {
30	            throw new OwnerDailyLimitException(businessDay, count);
31	        }
32	    }
33	}
