1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.Regions;
5	import org.springframework.samples.petclinic.model.CustomerCode;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Runs after {@link BuildOwner} and before {@link SaveOwner} on {@code POST /api/owners}. Assigns the
10	 * new owner's {@code customerCode} formatted {@code <REGION>-<HASH8>}, where REGION is the region code
11	 * derived from the postcode (see {@link Regions#regionForPostcode(String)}, e.g. {@code NSW}, or
12	 * {@code UNKNOWN} when the postcode resolves to no known region) and HASH8 is the first 8 upper-case
13	 * hex characters of {@code SHA-256(normalizedTelephone + lastName)} (see
14	 * {@link CustomerCode#hash8(String, String)}, e.g. {@code NSW-1A2B3C4D}). The identity no longer uses
15	 * per-city sequence numbers, so this step depends only on the owner's own fields.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        String region = Regions.regionForPostcode(owner.getPostcode());
21	        String hash8 = CustomerCode.hash8(owner.getTelephone(), owner.getLastName());
22	        owner.setCustomerCode(CustomerCode.format(region, hash8));
23	    }
24	}
