1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after {@link BuildOwner} and before {@link SaveOwner} on {@code POST /api/owners}. Records the
9	 * new owner's {@code namesakeCount}: the number of existing owners that, at the time of this create,
10	 * share the same {@code firstName} and {@code lastName} compared case-insensitively. The owner is
11	 * still unsaved, so it is not counted against itself.
12	 */
13	public class CountNamesakes {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (equalsIgnoreCase(firstName, existing.getFirstName())
21	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
22	                count++;
23	            }
24	        }
25	        owner.setNamesakeCount(count);
26	    }
27	
28	    private static boolean equalsIgnoreCase(String a, String b) {
29	        return a == null ? b == null : a.equalsIgnoreCase(b);
30	    }
31	}
