1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Runs just before the responder on both {@code GET /api/owners/{ownerId}} and {@code POST /api/owners}.
12	 * Computes the {@code bulkSignupWarning} flag carried on the owner response: it is {@code true} once more
13	 * than {@value #BULK_SIGNUP_THRESHOLD} other owners share this owner's effective (business-day)
14	 * registration date, otherwise {@code false}.
15	 *
16	 * <p>The effective day is derived through {@link BusinessDay} and the per-day count through
17	 * {@link DailyRegistrations#countOn}, exactly as the per-day create-limit rule
18	 * ({@link CheckOwnerDailyLimit}) does, so the two rules cannot drift. The owner itself is excluded from
19	 * the count, so on a create it reflects the owners already created that day and on a read the other
20	 * owners sharing the day.
21	 */
22	public class CheckBulkSignup {
23	
24	    /** More than this many other owners already registered for the day raises the warning. */
25	    static final int BULK_SIGNUP_THRESHOLD = 80;
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository, Out<Boolean> bulkSignupWarning) {
28	        LocalDate businessDay = BusinessDay.effective(owner.getRegistrationDate());
29	        int count = DailyRegistrations.countOn(ownerRepository, businessDay, owner.getId());
30	        bulkSignupWarning.set(count > BULK_SIGNUP_THRESHOLD);
31	    }
32	}
