11	
12	public class RespondWithOwnerCreated {
13	
14	    public void service(@Val Owner owner, @Val Boolean bulkSignupWarning, OwnerMapper ownerMapper,
15	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
16	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
17	        dto.setBulkSignupWarning(bulkSignupWarning);
18	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
19	    }
20	}
