3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * The single home for "how many owners share a registration day" — the domain concept behind both the
10	 * per-day create-limit rule ({@link CheckOwnerDailyLimit}) and the bulk-signup warning
11	 * ({@link CheckBulkSignup}). Callers derive the effective business day once via {@link BusinessDay} and
12	 * pass it here, so the day definition and the count scan each live in exactly one place.
13	 */
14	final class DailyRegistrations {
15	
16	    private DailyRegistrations() {
17	    }
18	
19	    /**
20	     * Counts owners whose {@code registrationDate} equals {@code businessDay}. When {@code excludeId} is
21	     * non-null the owner with that id is not counted (so a persisted owner is not counted against
22	     * itself); pass {@code null} to count every owner on the day.
23	     */
24	    static int countOn(OwnerRepository ownerRepository, LocalDate businessDay, Integer excludeId) {
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (excludeId != null && excludeId.equals(existing.getId())) {
28	                continue;
29	            }
30	            if (businessDay != null && businessDay.equals(existing.getRegistrationDate())) {
31	                count++;
32	            }
33	        }
34	        return count;
35	    }
36	}
